<template><div class="overview-page"><div class="overview-hero"><div><span class="eyebrow">学习情况</span><h2>学生自适应练习概览</h2><p>查看学生真正完成的自适应练习，不把仅打开页面或启动失败算作练习。</p></div><button class="iq-btn iq-btn-secondary" :disabled="loading" @click="load">刷新数据</button></div><div v-if="loading" class="iq-card empty">正在读取学生练习情况...</div><template v-else><div class="scope-note">统计口径：学生成功提交至少1道题后才计入；“完成题数”是已经提交的题数，“正确率”是答对题数÷完成题数。</div><div class="metric-grid"><div class="metric"><b>{{data.users.length}}</b><span>学生账号总数</span><small>包括尚未练习的学生</small></div><div class="metric"><b>{{activeStudents}}</b><span>实际练习人数</span><small>至少提交过1道题</small></div><div class="metric"><b>{{totalSessions}}</b><span>有效练习次数</span><small>不统计0题空记录</small></div><div class="metric"><b>{{overallAccuracy}}%</b><span>已答题整体正确率</span><small>答对题数÷完成题数</small></div></div><div class="iq-card table-card"><div class="card-title"><h3>学生表现</h3><span>按最近有效练习时间排序</span></div><table><thead><tr><th>学生</th><th>有效练习</th><th>已完成题数</th><th>正确率</th><th>最高难度</th><th>最近练习</th><th>建议关注</th></tr></thead><tbody><tr v-for="u in data.users" :key="u.userId"><td><b>{{u.nickname||u.username}}</b><small>{{u.username}}</small></td><td>{{u.sessionCount}}次</td><td>{{u.answeredCount}}题</td><td><span class="accuracy" :class="accuracyClass(u.accuracy)">{{u.accuracy}}%</span></td><td>{{Number(u.sessionCount)?`${u.highestDifficulty}级（${difficultyLabel(u.highestDifficulty)}）`:'-'}}</td><td>{{formatTime(u.lastPracticeAt)}}</td><td>{{advice(u)}}</td></tr></tbody></table></div><div class="iq-card recent-card"><div class="card-title"><h3>最近有效练习</h3><span>只展示至少完成1道题的记录</span></div><div v-if="!data.recentSessions.length" class="empty-mini">目前还没有学生成功提交自适应练习题。</div><div v-else class="session-list"><div v-for="s in data.recentSessions.slice(0,12)" :key="s.id" class="session"><div><b>{{s.nickname||s.username}}</b><span>{{rangeText(s)}}</span></div><div><b>已完成 {{s.answered_count}}/{{s.planned_count}} 题</b><span>答对{{s.correct_count}}题 · 当前{{s.current_difficulty}}级</span></div><em :class="s.status">{{statusText(s)}}</em></div></div></div></template></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{getAdaptiveOverview}from'@/api/practice';const emit=defineEmits(['toast']),loading=ref(false),data=ref({users:[],recentSessions:[]});const load=async()=>{loading.value=true;try{data.value=await getAdaptiveOverview()}catch(e){emit('toast',e.message||'读取失败','error')}finally{loading.value=false}};const activeStudents=computed(()=>data.value.users.filter(u=>Number(u.sessionCount)>0).length),totalSessions=computed(()=>data.value.users.reduce((s,u)=>s+Number(u.sessionCount),0)),overallAccuracy=computed(()=>{const a=data.value.users.reduce((s,u)=>s+Number(u.answeredCount),0),c=data.value.users.reduce((s,u)=>s+Number(u.correctCount),0);return a?Math.round(c/a*100):0});const difficultyLabel=n=>Number(n)<=2?'简单':Number(n)<=4?'中等':'困难',accuracyClass=n=>Number(n)>=80?'good':Number(n)<=40?'weak':'normal',advice=u=>!Number(u.sessionCount)?'尚未开始':Number(u.accuracy)<=40?'需要重点巩固':Number(u.accuracy)>=80?'表现稳定':'继续观察',statusText=s=>s.status==='completed'?'按计划完成':`未完成，还差${Math.max(0,Number(s.planned_count)-Number(s.answered_count))}题`,rangeText=s=>`${s.chapters?`第${String(s.chapters).replaceAll(',','、')}章`:'全部章节'} · ${s.knowledge_keyword||'不限知识点'}`,formatTime=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'-';onMounted(load);</script>
<style scoped>.overview-page{display:grid;gap:18px;max-width:1180px}.overview-hero{display:flex;align-items:center;justify-content:space-between;padding:26px 30px;border-radius:18px;background:linear-gradient(135deg,#312e81,#6366f1 65%,#818cf8);color:white;box-shadow:0 14px 35px #4f46e533}.overview-hero h2{margin:5px 0;font-size:28px}.overview-hero p{margin:0;color:#e0e7ff}.eyebrow{font-size:12px;letter-spacing:2px}.scope-note{padding:12px 15px;border-radius:10px;background:#eff6ff;color:#1d4ed8}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.metric{display:grid;padding:20px;border:1px solid #e2e8f0;border-radius:14px;background:white}.metric b{font-size:28px;color:#312e81}.metric span{color:#64748b}.metric small{color:#94a3b8;margin-top:4px}.table-card,.recent-card{padding:22px}.card-title{display:flex;justify-content:space-between;align-items:center}.card-title h3{margin:0 0 15px}.card-title span{color:#64748b;font-size:13px}table{width:100%;border-collapse:collapse}th,td{padding:13px 10px;border-bottom:1px solid #eef2f7;text-align:left}td small{display:block;color:#94a3b8}.accuracy{padding:4px 9px;border-radius:20px}.accuracy.good{background:#dcfce7;color:#15803d}.accuracy.normal{background:#fef3c7;color:#a16207}.accuracy.weak{background:#fee2e2;color:#b91c1c}.session-list{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.session{display:flex;justify-content:space-between;align-items:center;padding:13px;background:#f8fafc;border-radius:10px}.session div{display:grid}.session span{font-size:12px;color:#64748b}.session em{max-width:140px;text-align:center;font-style:normal;padding:4px 8px;border-radius:12px;background:#fef3c7;color:#a16207}.session em.completed{background:#dcfce7;color:#15803d}.empty,.empty-mini{padding:50px;text-align:center}.empty-mini{color:#64748b}@media(max-width:800px){.metric-grid{grid-template-columns:repeat(2,1fr)}.session-list{grid-template-columns:1fr}.table-card{overflow:auto}}</style>
